    # 1. Bulk discount: 12% off when qty is at least 9 (rounded down to whole cents).
    if qty >= 9:
        amount -= (amount * 12) // 100

    # 2. Loyalty: flat 250 cents off for customers whose name starts with H/h.
    customer = order.get("customer") or ""
    if customer[:1].lower() == "h":
        amount -= 250
    if amount < 0:
        amount = 0

    # 3. Coupon: SAMU gives 7% off (rounded down); any other value is ignored.
    if order.get("coupon") == "SAMU":
        amount -= (amount * 7) // 100

    # 4. Rush surcharge: 400 cents, never discounted.
    if order.get("rush"):
        amount += 400

    # 5. Minimum charge for any non-empty order.
    if amount < 1900:
        amount = 1900

    return int(amount)
